tags.expression:
dateDiff(
    if(
        dateExtract(now(), "hour") >= 7,
        toDate(dateFormat(now(), "yyyy-MM-dd") + " 07:00:00"),
        addDays(toDate(dateFormat(now(), "yyyy-MM-dd") + " 07:00:00"), -1)
    ),
    now(),
    "seconds"
)

if(
    isNull((({[.]../Time Since 7} - {[.]Scheduled_Downtime/Not_Scheduled_Adjustment}) - {[.]Total_Downtime})),
    0,
    if(
        ({[.]../Time Since 7} - {[.]Scheduled_Downtime/Not_Scheduled_Adjustment}) < 0,
		0,
        (({[.]../Time Since 7} - {[.]Scheduled_Downtime/Not_Scheduled_Adjustment}) - {[.]Total_Downtime})
        )
	)

tags.query:
SELECT CASE 
    WHEN EXISTS (
        SELECT 1 
        FROM Scheduled_Stops
        WHERE NOW() BETWEEN Start_Date AND End_Date
    ) THEN 1 ELSE 0 END AS result;
